/* @author MILO-GAO(高振銘)@2020 */ package page2020.client;import java.io.ByteArrayInputStream;import java.util.Collections;import java.util.HashMap;import java.util.Map;import javax.annotation.PostConstruct;import org.dom4j.Document;import org.dom4j.Element;import org.dom4j.Node;import org.dom4j.io.SAXReader;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.util.StringUtils;import org.springframework.web.reactive.function.client.WebClient;import org.springframework.web.reactive.function.client.WebClient.RequestBodySpec;import page2020.core.Log;import page2020.util.EmptyUtil;@Servicepublic class WebProxy {	private static Logger log = LoggerFactory.getLogger(WebProxy.class);	@Value("${default.client.1}")	private String client01;	@Value("${default.client.2}")	private String client02;	@Value("${default.client.3}")	private String client03;	@Value("${default.api.1}")	private String api01;	@Value("${default.api.2}")	private String api02;	@Value("${default.api.3}")	private String api03;	@Autowired	private BCryptPasswordEncoder encorder;	private Map<String, ClientConfig> configs = new HashMap<String, ClientConfig>();	private Map<String, String> urls = new HashMap<String, String>();	private Map<String, String> passports = new HashMap<String, String>();	private Map<String, PageClient> pages = Collections.synchronizedMap(new HashMap<String, PageClient>());	private Map<String, RestClient> rests = Collections.synchronizedMap(new HashMap<String, RestClient>());	private Map<String, RestClient> apiClients = Collections.synchronizedMap(new HashMap<String, RestClient>());	@PostConstruct	public void initial() {		this.addConfig(this.client01);		this.addConfig(this.client02);		this.addConfig(this.client03);		this.addApi(this.api01);		this.addApi(this.api02);		this.addApi(this.api03);	}	public ClientConfig config(String name) {		if (this.configs.containsKey(name)) {			return this.configs.get(name);		}		return null;	}	public PageClient page(String name) {		if (this.pages.containsKey(name)) {			return this.pages.get(name);		}		if (this.configs.containsKey(name)) {			PageClient page = new PageClient(this.configs.get(name));			this.pages.put(name, page);			return page;		}		return null;	}	public RestClient rest(String name) {		if (this.rests.containsKey(name)) {			return this.rests.get(name);		}		if (this.configs.containsKey(name)) {			RestClient rest = new RestClient(this.configs.get(name));			this.rests.put(name, rest);			return rest;		}		return null;	}	public RequestBodySpec api(String name, String url) {		RestClient client = null;		if (this.apiClients.containsKey(name)) {			client = this.apiClients.get(name);		} else if (this.urls.containsKey(name)) {			client = new RestClient(this.urls.get(name));			this.apiClients.put(name, client);		} else {			return null;		}		if (EmptyUtil.is(url)) {			return client.api();		} else {			return client.api(url);		}	}	public RequestBodySpec api(String name) {		return this.api(name, null);	}	public WebClient client(String name) {		RestClient rest = this.rest(name);		if (rest != null) {			return rest.instance();		}		return null;	}	public Document document(String xml) {		Document document = null;		try {			document = new SAXReader().read(new ByteArrayInputStream(xml.getBytes("UTF-8")));		} catch (Exception ex) {			log.error(ex.toString());			return null;		}		return document;	}	public void addElement(Element parent, String name, String value) {		Element e = parent.addElement(name);		if (EmptyUtil.not(value)) {			e.setText(value);		}	}	public String value(Document doc, String name) {		Node node = doc.selectSingleNode("/" + "/" + name);		if (node != null) {			return node.getText();		}		return "";	}	private void addConfig(String client) {		if (EmptyUtil.not(client)) {			ClientConfig config = new ClientConfig(client);			if (config.isActive()) {				String passport = this.encorder.encode(config.passKey());				config.setPassport(passport);								this.configs.put(config.getName(), config);				this.passports.put(config.getName(), passport);				if (Log.client) {					log.info("config: " + config.toString());				}			}		}			}	private void addApi(String api) {		if (EmptyUtil.not(api)) {			String[] tokens = StringUtils.trimAllWhitespace(api).split(";");			if (tokens.length == 3 && tokens[0].equals("1")) {				this.urls.put(tokens[1], tokens[2]);			}		}	}}